def partition_build_events(apps, schema_editor):
    # Every other event table became partitioned in 0144. This one is new and
    # empty, so it is simply made again as a partitioned table, keeping the
    # columns, defaults, identity and checks CreateModel gave it and putting its
    # indexes back under the names Django knows them by. Partitions are added
    # per hour as builds are created, as for the others.
    tmp = f'tmp_{EVENT_TABLE}'
    with schema_editor.connection.cursor() as cursor:
        cursor.execute(f'ALTER TABLE {EVENT_TABLE} RENAME TO {tmp}')
        cursor.execute(
            'SELECT indexdef FROM pg_indexes WHERE schemaname = current_schema() AND tablename = %s AND indexname <> %s',
            [tmp, f'{EVENT_TABLE}_pkey'],
        )
        index_definitions = [row[0] for row in cursor.fetchall()]
        cursor.execute(
            f'CREATE TABLE {EVENT_TABLE} (LIKE {tmp} INCLUDING DEFAULTS INCLUDING IDENTITY INCLUDING CONSTRAINTS INCLUDING STORAGE INCLUDING COMMENTS) '
            'PARTITION BY RANGE(job_created)'
        )
        cursor.execute(f'DROP TABLE {tmp}')
        # constraints on a partitioned table must include the partition key
        cursor.execute(f'ALTER TABLE ONLY {EVENT_TABLE} ADD CONSTRAINT {EVENT_TABLE}_pkey_new PRIMARY KEY (id, job_created)')
        for definition in index_definitions:
            cursor.execute(definition.replace(f' ON {tmp} ', f' ON {EVENT_TABLE} ').replace(f'.{tmp} ', f'.{EVENT_TABLE} '))


