def find_execution_environment_files(apps, schema_editor):
    # Projects list their definition files the way they list playbooks, as of
    # their last sync. Fill that in from what is on disk here now, so builders
    # can be set up before every project has been synced again.
    import os

    from django.conf import settings as django_settings

    from ascender.main.utils.ansible import skip_directory

    Project = apps.get_model('main', 'Project')
    for project in Project.objects.exclude(scm_type='').exclude(local_path='').iterator():
        project_path = os.path.join(django_settings.PROJECTS_ROOT, project.local_path)
        if not os.path.isdir(project_path):
            continue
        found = []
        for dirpath, dirnames, filenames in os.walk(project_path):
            if skip_directory(dirpath):
                continue
            for filename in filenames:
                if filename in ('execution-environment.yml', 'execution-environment.yaml'):
                    found.append(os.path.relpath(os.path.join(dirpath, filename), project_path))
        if found:
            project.execution_environment_files = sorted(found, key=str.lower)
            project.save(update_fields=['execution_environment_files'])


